/* ---------- Original-Texturen (vorkomponiert, fertig gefärbt) ---------- */
export const TEXTURES = {
  light:  "data:image/jpeg;base64,",
  dark:   "data:image/jpeg;base64,",
  accent: "data:image/jpeg;base64,",
  tile:   "data:image/jpeg;base64,",
  chip:   "data:image/jpeg;base64,",
};

/* ---------- Schatten (weiche Tiefen, nur Ebenentrennung) ---------- */
const SHADOWS: Record<number, ViewStyle> = {
  0: {},
  1: { shadowColor: "#1C0C07", shadowOpacity: 0.15, shadowRadius: 6,
       shadowOffset: { width: 0, height: 2 }, elevation: 2 },
  2: { shadowColor: "#1C0C07", shadowOpacity: 0.18, shadowRadius: 12,
       shadowOffset: { width: 0, height: 4 }, elevation: 5 },
  3: { shadowColor: "#1C0C07", shadowOpacity: 0.20, shadowRadius: 20,
       shadowOffset: { width: 0, height: 8 }, elevation: 9 },
};

/* ---------- PaperCard ----------
   Die EINZIGE erlaubte Papierkarte.
   variant: light | dark | accent | tile | chip
   shape:   1 | 2 | 3   (benachbarte Karten rotieren!)
   shadow:  0 | 1 | 2 | 3
   Inhalt bekommt automatisch 20px Innenabstand (über contentStyle
   anpassbar, aber nie unter 16px – die Welle schneidet 2-3% ab). */

type PaperCardProps = {
  variant?: "light" | "dark" | "accent" | "tile" | "chip";
  shape?: 1 | 2 | 3;
  shadow?: 0 | 1 | 2 | 3;
  style?: StyleProp<ViewStyle>;        // Außenmaße, Margins
  contentStyle?: StyleProp<ViewStyle>; // Innenlayout, Padding
  children?: React.ReactNode;
};

let uid = 0;

export function PaperCard({
  variant = "light",
  shape = 1,
  shadow = 1,
  style,
  contentStyle,
  children,
}: PaperCardProps) {
  const wave = WAVES[shape - 1];
  const texture = TEXTURES[variant];
  const clipId = React.useRef(`pw${++uid}`).current;
  const baseColor =
    variant === "dark" ? COLORS.coffee700
    : variant === "accent" ? COLORS.accent100
    : variant === "tile" ? COLORS.accentTile
    : variant === "chip" ? COLORS.accent200
    : COLORS.paperLight;

  return (
    <View style={[SHADOWS[shadow], style]}>
      <Svg
        style={StyleSheet.absoluteFill}
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        pointerEvents="none"
      >
        <Defs>
          <ClipPath id={clipId}>
            <Path d={wave} />
          </ClipPath>
        </Defs>
        {/* Grundfarbe als Fallback, darüber die Original-Textur */}
        <Path d={wave} fill={baseColor} />
        <SvgImage
          href={{ uri: texture }}
          x="0" y="0" width="100" height="100"
          preserveAspectRatio="xMidYMid slice"
          clipPath={`url(#${clipId})`}
        />
      </Svg>
      <View style={[{ padding: 20 }, contentStyle]}>{children}</View>
    </View>
  );
}

